-- =============================================================================
-- Migración: Catálogo Dálida Beauty & Spa (áreas + servicios con grupos e imágenes)
-- Idempotente (upsert por slug). Ejecutar en el SQL Editor de Supabase (schema spanails).
-- =============================================================================

alter table spanails.categorias add column if not exists icono text;
alter table spanails.servicios  add column if not exists grupo text;

-- ---- Áreas ----
on conflict (slug) do update set nombre=excluded.nombre, descripcion=excluded.descripcion, icono=excluded.icono, orden=excluded.orden, activo=true;

-- ---- Servicios ----
with c as (select id, slug from spanails.categorias)
on conflict (slug) do update set categoria_id=excluded.categoria_id, nombre=excluded.nombre, grupo=excluded.grupo, imagen_url=excluded.imagen_url, orden=excluded.orden, activo=true;

-- Total: 20 areas, 272 servicios.
